def max_depth_brute(root):
    if root is None:
        return 0
    paths = []
    def dfs(node, length):
        if node is None:
            return
        if node.left is None and node.right is None:
            paths.append(length)                       # record every complete path length
            return
        dfs(node.left, length + 1)
        dfs(node.right, length + 1)
    dfs(root, 1)
    return max(paths) if paths else 0

